/*
 * A256275  Decimal equivalent of the binary string generated by the negation
 *          of the n X n identity matrix.
 * https://oeis.org/A256275
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = ((2^(n^2) - 2)*(2^n - 1))/(2*2^n - 1)
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 5, u64 n <= 8, u128 n <= 11,
 *            big any n
 * Helpers:   pow2
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/pow2.h"

/* Computes the n-th term of OEIS A256275.  The index n is 1‑based
   (a(1) = 0).  For n == 0 the function returns 0. */
seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0;        /* safety for out‑of‑range calls */

    /* 2^n  */
    seq_t pow2_n = pow2(n);

    /* 2^(n^2)  */
    seq_t pow2_nn = pow2(n * n);

    /* (2^(n^2) - 2)  */
    seq_t term1 = pow2_nn - (seq_t)2;

    /* (2*2^n - 1)  */
    seq_t denom = (seq_t)2 * pow2_n - (seq_t)1;

    /* term1/denom is an integer (see OEIS formula) */
    seq_t t1 = term1 / denom;

    /* (2^n - 1)  */
    seq_t term2 = pow2_n - (seq_t)1;

    /* Final result: (term1/denom) * (2^n - 1) */
    seq_t result = t1 * term2;
    return result;
}
